1	// Render the live app's terminal grid to a crisp SVG "screenshot".
2	//
3	// The PTY harness already knows every cell's glyph, colors, and attributes —
4	// this script boots the app (or runs a preparation snippet first), captures
5	// the completed frame, and emits an SVG that reproduces the grid exactly:
6	// per-cell RGB/palette colors, bold/italic/dim, merged background runs.
7	// SVG because the machine is headless and the output beats a bitmap anyway:
8	// a few hundred KB, crisp at any zoom, perfect for a static docs site.
9	//
10	// Usage:
11	//   bun scripts/harness/screenshot-svg.ts --out shot.svg [--open DIR]
12	//     [--size N] [--geometry CxR] [--eval 'await app.key("Control+Shift+t").waitForText("LIVE")']
13	//
14	// The --eval snippet runs with `app` (a DriveSession) before capture — use it
15	// to open panels and navigate to the composition you want in the shot.
16	
17	import { writeFileSync } from 'node:fs';
18	import { DriveScriptRunner } from './DriveSession';
19	import type { HarnessSnapshot, HarnessSnapshotCell } from './HarnessSnapshot';
20	
21	const CELL_WIDTH = 9.6;
22	const CELL_HEIGHT = 21;
23	const FONT_SIZE = 15.5;
24	const BASELINE_OFFSET = 15.5;
25	const DEFAULT_FOREGROUND = '#c8ccd4';
26	const DEFAULT_BACKGROUND = '#0d1016';
27	const FONT_FAMILY =
28	  "'JetBrains Mono','Fira Code','SF Mono',Menlo,Consolas,monospace";
29	
30	/** Standard xterm 256-color palette (16 system + 216 cube + 24 grays). */
31	function paletteToRgb(index: number): string {
32	  const system = [
33	    '#000000',
34	    '#cd3131',
35	    '#0dbc79',
36	    '#e5e510',
37	    '#2472c8',
38	    '#bc3fbc',
39	    '#11a8cd',
40	    '#e5e5e5',
41	    '#666666',
42	    '#f14c4c',
43	    '#23d18b',
44	    '#f5f543',
45	    '#3b8eea',
46	    '#d670d6',
47	    '#29b8db',
48	    '#ffffff',
49	  ];
50	  if (index < 16) return system[index] ?? DEFAULT_FOREGROUND;
51	  if (index < 232) {
52	    const cube = index - 16;
53	    const steps = [0, 95, 135, 175, 215, 255];
54	    const red = steps[Math.floor(cube / 36) % 6] ?? 0;
55	    const green = steps[Math.floor(cube / 6) % 6] ?? 0;
56	    const blue = steps[cube % 6] ?? 0;
57	    return rgbHex(red, green, blue);
58	  }
59	  const gray = 8 + (index - 232) * 10;
60	  return rgbHex(gray, gray, gray);
61	}
62	
63	function rgbHex(red: number, green: number, blue: number): string {
64	  const part = (value: number) => value.toString(16).padStart(2, '0');
65	  return `#${part(red)}${part(green)}${part(blue)}`;
66	}
67	
68	/** A packed 24-bit color from the emulator becomes #rrggbb. */
69	function packedToRgb(packed: number): string {
70	  return rgbHex((packed >> 16) & 0xff, (packed >> 8) & 0xff, packed & 0xff);
71	}
72	
73	function foregroundOf(cell: HarnessSnapshotCell): string {
