// Rewrites box-drawing/block glyphs inside screenshot-svg <text> runs into
// vector shapes that span the full cell — text glyphs don't reach cell
// edges, which shows as dashed splitters/borders. Usage: node script file...
import { readFileSync, writeFileSync } from 'node:fs';

const CELL_WIDTH = 9.6;
const CELL_HEIGHT = 21;
const OVERDRAW = 0.6;
const BASELINE = 15.5;
const STROKE = 1.5;

const decode = (text) =>
  text.replaceAll('&lt;', '<').replaceAll('&gt;', '>').replaceAll('&amp;', '&');
const encode = (text) =>
  text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');

const isBox = (ch) => {
  const code = ch.codePointAt(0);
  return code >= 0x2500 && code <= 0x259f;
};

// One glyph → SVG shape(s). (x, top) is the cell's top-left; fill is the run color.
function shapesFor(ch, x, top, fill) {
  const cx = x + CELL_WIDTH / 2;
  const cy = top + CELL_HEIGHT / 2;
  const right = x + CELL_WIDTH;
  const bottom = top + CELL_HEIGHT + OVERDRAW;
  const radius = CELL_WIDTH / 2;
  const half = STROKE / 2;
  const rect = (rx, ry, rw, rh) =>
    `<rect x="${round(rx)}" y="${round(ry)}" width="${round(rw)}" height="${round(rh)}" fill="${fill}" shape-rendering="crispEdges"/>`;
  const path = (d) =>
    `<path d="${d}" fill="none" stroke="${fill}" stroke-width="${STROKE}"/>`;
  switch (ch) {
    case '─': return rect(x, cy - half, CELL_WIDTH, STROKE);
    case '│': return rect(cx - half, top, STROKE, CELL_HEIGHT + OVERDRAW);
    case '╭': return path(`M${round(right)} ${round(cy)} H${round(cx + radius)} Q${round(cx)} ${round(cy)} ${round(cx)} ${round(cy + radius)} V${round(bottom)}`);
    case '╮': return path(`M${round(x)} ${round(cy)} H${round(cx - radius)} Q${round(cx)} ${round(cy)} ${round(cx)} ${round(cy + radius)} V${round(bottom)}`);
    case '╰': return path(`M${round(cx)} ${round(top)} V${round(cy - radius)} Q${round(cx)} ${round(cy)} ${round(cx + radius)} ${round(cy)} H${round(right)}`);
    case '╯': return path(`M${round(cx)} ${round(top)} V${round(cy - radius)} Q${round(cx)} ${round(cy)} ${round(cx - radius)} ${round(cy)} H${round(x)}`);
    case '┌': return path(`M${round(right)} ${round(cy)} H${round(cx)} V${round(bottom)}`);
    case '┐': return path(`M${round(x)} ${round(cy)} H${round(cx)} V${round(bottom)}`);
    case '└': return path(`M${round(cx)} ${round(top)} V${round(cy)} H${round(right)}`);
    case '┘': return path(`M${round(cx)} ${round(top)} V${round(cy)} H${round(x)}`);
    case '├': return rect(cx - half, top, STROKE, CELL_HEIGHT + OVERDRAW) + rect(cx, cy - half, right - cx, STROKE);
    case '┤': return rect(cx - half, top, STROKE, CELL_HEIGHT + OVERDRAW) + rect(x, cy - half, cx - x, STROKE);
    case '┬': return rect(x, cy - half, CELL_WIDTH, STROKE) + rect(cx - half, cy, STROKE, bottom - cy);
    case '┴': return rect(x, cy - half, CELL_WIDTH, STROKE) + rect(cx - half, top, STROKE, cy - top);
    case '┼': return rect(x, cy - half, CELL_WIDTH, STROKE) + rect(cx - half, top, STROKE, CELL_HEIGHT + OVERDRAW);
    case '█': return rect(x, top, CELL_WIDTH, CELL_HEIGHT + OVERDRAW);
    case '▀': return rect(x, top, CELL_WIDTH, CELL_HEIGHT / 2);
    case '▄': return rect(x, cy, CELL_WIDTH, bottom - cy);
    case '▌': return rect(x, top, CELL_WIDTH / 2, CELL_HEIGHT + OVERDRAW);
    case '▐': return rect(cx, top, CELL_WIDTH / 2, CELL_HEIGHT + OVERDRAW);
    case '▏': return rect(x, top, CELL_WIDTH / 8, CELL_HEIGHT + OVERDRAW);
    case '▎': return rect(x, top, CELL_WIDTH / 4, CELL_HEIGHT + OVERDRAW);
    case '▍': return rect(x, top, CELL_WIDTH * 0.375, CELL_HEIGHT + OVERDRAW);
    case '▋': return rect(x, top, CELL_WIDTH * 0.625, CELL_HEIGHT + OVERDRAW);
    case '▊': return rect(x, top, CELL_WIDTH * 0.75, CELL_HEIGHT + OVERDRAW);
    case '▉': return rect(x, top, CELL_WIDTH * 0.875, CELL_HEIGHT + OVERDRAW);
    default: return null; // unknown — keep as text
  }
}

const round = (value) => {
  const rounded = Math.round(value * 100) / 100;
  return Number.isInteger(rounded) ? String(rounded) : String(rounded);
};

for (const file of process.argv.slice(2)) {
  let replacedGlyphs = 0;
  const source = readFileSync(file, 'utf8');
  const output = source.replace(
    /<text x="([\d.]+)" y="([\d.]+)"([^>]*)>([^<]*)<\/text>/g,
    (whole, xText, yText, attributes, rawContent) => {
      const content = decode(rawContent);
      if (![...content].some((ch) => isBox(ch) && shapesFor(ch, 0, 0, '#fff'))) return whole;
      const startX = Number(xText);
      const top = Number(yText) - BASELINE;
      const fill = attributes.match(/fill="([^"]+)"/)?.[1] ?? '#c8ccd4';
      const characters = [...content];
      const pieces = [];
      let textStart = 0;
      let textBuffer = '';
      const flushTextSegment = (endIndex) => {
        if (!textBuffer.trim()) { textBuffer = ''; return; }
        const segmentX = startX + textStart * CELL_WIDTH;
        pieces.push(
          `<text x="${round(segmentX)}" y="${yText}"${attributes} textLength="${round(textBuffer.length * CELL_WIDTH)}" lengthAdjust="spacingAndGlyphs" xml:space="preserve">${encode(textBuffer)}</text>`
            .replace(/ textLength="[\d.]+" lengthAdjust="spacingAndGlyphs"(?=.* textLength=)/, ''),
        );
        textBuffer = '';
      };
      for (let index = 0; index < characters.length; index++) {
        const ch = characters[index];
        const shape = isBox(ch)
          ? shapesFor(ch, startX + index * CELL_WIDTH, top, fill)
          : null;
        if (shape) {
          flushTextSegment(index);
          pieces.push(shape);
          replacedGlyphs++;
        } else {
          if (!textBuffer) textStart = index;
          textBuffer += ch;
        }
      }
      flushTextSegment(characters.length);
      return pieces.join('');
    },
  );
  writeFileSync(file, output);
  console.log(`${file}: vectorized ${replacedGlyphs} box glyphs`);
}

