node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  for (const [theme, name] of [['dark','tables-dark'],['light','tables-light']]) {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, colorScheme: theme === 'dark' ? 'dark' : 'light' });
    await page.goto('http://localhost:5188/guide/performance', { waitUntil: 'networkidle' });
    if (theme === 'dark') await page.evaluate(() => document.documentElement.classList.add('dark'));
    else await page.evaluate(() => document.documentElement.classList.remove('dark'));
    await page.evaluate(() => { const tables = document.querySelectorAll('.vp-doc table'); tables[1]?.scrollIntoView({ block: 'center' }); });
    await page.waitForTimeout(400);
    await page.screenshot({ path: '$S/' + name + '.png' });
    await page.close();
  }
  await browser.close();
  console.log('shots');
})();
"
kill %1 2>/dev/null

